import type { Page, Route } from '@playwright/test';

export const tournamentId = 'synthetic-wide-overlay-tournament';

const organizer = {
  id: 'synthetic-wide-organizer',
  email: 'wide-organizer@example.test',
  fullName: 'Wide Overlay Organizer',
  phoneNumber: '0900000009',
  roles: ['ORGANIZER'],
  gender: 'MALE',
  isEmailVerified: true,
  profile: { fullName: 'Wide Overlay Organizer', phoneNumber: '0900000009' },
};

const tournament = {
  id: tournamentId,
  name: 'Synthetic wide overlay tournament',
  status: 'PUBLISHED',
  matchType: 'SINGLES',
  genderRestriction: 'MALE',
  entryFee: 0,
  maxParticipants: 32,
  isRegistrationLocked: false,
  category: { name: 'Badminton', slug: 'badminton' },
  tournamentConfig: { registrationMode: 'APPROVAL' },
};

export const divisionFixture = {
  id: 'synthetic-wide-division',
  name: 'Synthetic wide division',
  matchType: 'SINGLES',
  genderRestriction: 'MALE',
  entryFee: 0,
  maxParticipants: 32,
  bracketType: 'ROUND_ROBIN',
  _count: { participants: 1 },
};

/**
 * A knockout with two rounds. Without this the bracket renders its empty state,
 * so no layout, magnify button or round navigation can actually be exercised.
 * Opt-in through `openManage(page, { withBracket: true })`.
 */
export const bracketFixture = {
  stages: [
    {
      id: 'bracket-stage-ko',
      name: 'Vòng loại trực tiếp',
      type: 'SINGLE_ELIMINATION',
      order: 1,
      groups: [
        {
          id: 'bracket-group-ko',
          name: 'Vòng loại trực tiếp',
          matches: [
            {
              id: 'ko-r1-m1',
              roundNumber: 1,
              leg: null,
              matchOrder: 1,
              bracketBranch: 'A',
              status: 'COMPLETED',
              isBye: false,
              participant1: { id: 'p1', teamName: 'Đội Bão', seed: 1, members: [{ userId: 'u1', fullName: 'Bão' }] },
              participant2: { id: 'p2', teamName: 'Đội Gió', seed: 2, members: [{ userId: 'u2', fullName: 'Gió' }] },
              participant1Id: 'p1',
              participant2Id: 'p2',
              winnerId: 'p1',
              p1SetsWon: 2,
              p2SetsWon: 0,
              groupId: 'bracket-group-ko',
            },
            {
              id: 'ko-r1-m2',
              roundNumber: 1,
              leg: null,
              matchOrder: 2,
              bracketBranch: 'B',
              status: 'PENDING',
              isBye: false,
              participant1: { id: 'p3', teamName: 'Đội Mưa', seed: 3, members: [{ userId: 'u3', fullName: 'Mưa' }] },
              participant2: { id: 'p4', teamName: 'Đội Sấm', seed: 4, members: [{ userId: 'u4', fullName: 'Sấm' }] },
              participant1Id: 'p3',
              participant2Id: 'p4',
              winnerId: null,
              p1SetsWon: 0,
              p2SetsWon: 0,
              groupId: 'bracket-group-ko',
            },
            {
              id: 'ko-r2-m1',
              roundNumber: 2,
              leg: null,
              matchOrder: 1,
              bracketBranch: 'A',
              status: 'PENDING',
              isBye: false,
              participant1: null,
              participant2: null,
              participant1Id: null,
              participant2Id: null,
              participant1Placeholder: 'Chờ xác định',
              participant2Placeholder: 'Chờ xác định',
              winnerId: null,
              p1SetsWon: 0,
              p2SetsWon: 0,
              groupId: 'bracket-group-ko',
            },
          ],
        },
      ],
    },
  ],
};


const participant = {
  id: 'synthetic-wide-participant',
  tournamentId,
  tournamentDivisionId: divisionFixture.id,
  teamName: 'Wide overlay entrant',
  teamStatus: 'COMPLETE',
  isPaid: true,
  registeredAt: '2026-10-01T10:00:00.000Z',
  members: [{ userId: 'synthetic-wide-player', fullName: 'Wide overlay entrant', role: 'PLAYER' }],
};

export async function fulfillApi(route: Route, payload: unknown, status = 200) {
  const requestHeaders = route.request().headers();
  const headers = {
    'access-control-allow-origin': requestHeaders.origin ?? 'http://127.0.0.1:3001',
    'access-control-allow-credentials': 'true',
    'access-control-allow-methods': 'GET, POST, OPTIONS',
    'access-control-allow-headers': requestHeaders['access-control-request-headers'] ?? 'authorization,content-type',
  };

  if (route.request().method() === 'OPTIONS') {
    await route.fulfill({ status: 204, headers });
    return;
  }

  await route.fulfill({ status, headers, json: payload });
}

export async function openManage(
  page: Page,
  options: {
    divisions?: Array<typeof divisionFixture>;
    tab?: string;
    matchType?: 'SINGLES' | 'DOUBLES';
    withBracket?: boolean;
  } = {},
) {
  const matchType = options.matchType ?? 'SINGLES';
  const divisions = options.divisions ?? [{ ...divisionFixture, matchType }];
  const withBracket = options.withBracket ?? false;
  const currentTournament = { ...tournament, matchType };

  await page.addInitScript((user) => {
    localStorage.setItem('auth-storage', JSON.stringify({
      state: { user, isAuthenticated: true },
      version: 0,
    }));
  }, organizer);

  await page.route('**/api/v1/**', async (route) => {
    const pathname = new URL(route.request().url()).pathname;

    if (pathname.endsWith('/users/profile')) {
      await fulfillApi(route, organizer);
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}`) {
      await fulfillApi(route, { data: currentTournament });
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}/divisions`) {
      await fulfillApi(route, { data: divisions });
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}/bracket`) {
      await fulfillApi(route, { data: withBracket ? bracketFixture : { stages: [] } });
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}/manage/participants`) {
      await fulfillApi(route, { data: divisions.length === 0 ? [] : [participant] });
      return;
    }

    await fulfillApi(route, { data: [] });
  });

  const tab = options.tab ? `?tab=${options.tab}` : '';
  await page.goto(`/organizer/tournaments/${tournamentId}/manage${tab}`, { waitUntil: 'domcontentloaded' });
}

