import { expect, test, type Route } from '@playwright/test';

const tournamentId = 'synthetic-autosave-tournament';
const organizer = {
  id: 'synthetic-autosave-organizer',
  email: 'organizer@example.test',
  fullName: 'Organizer Test',
  roles: ['ORGANIZER'],
  gender: 'MALE',
  isEmailVerified: true,
  profile: { fullName: 'Organizer Test' },
};
const tournament = {
  id: tournamentId,
  name: 'Original Tournament',
  status: 'DRAFT',
  categoryId: 'synthetic-category',
  category: { name: 'Tennis', slug: 'tennis' },
  tournamentConfig: { registrationMode: 'APPROVAL' },
};

async function fulfillApi(route: Route, payload: unknown, status = 200) {
  const request = route.request();
  const requestHeaders = request.headers();
  const headers = {
    'access-control-allow-origin': requestHeaders.origin ?? 'http://localhost:3001',
    'access-control-allow-credentials': 'true',
    'access-control-allow-methods': 'GET, POST, PATCH, PUT, DELETE, OPTIONS',
    'access-control-allow-headers': requestHeaders['access-control-request-headers'] ?? 'authorization,content-type',
  };

  if (request.method() === 'OPTIONS') {
    await route.fulfill({ status: 204, headers });
    return;
  }

  await route.fulfill({ status, headers, json: payload });
}

test('autosaves registrationMode inside tournamentConfig', async ({ page }) => {
  await page.addInitScript((user) => {
    localStorage.setItem('auth-storage', JSON.stringify({
      state: { user, isAuthenticated: true },
      version: 0,
    }));
  }, organizer);

  const updateBodies: Array<Record<string, unknown>> = [];
  await page.route('**/api/v1/**', async (route) => {
    const request = route.request();
    const pathname = new URL(request.url()).pathname;

    if (pathname.endsWith('/users/profile')) {
      await fulfillApi(route, organizer);
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}` && request.method() === 'GET') {
      await fulfillApi(route, { data: tournament });
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}` && request.method() === 'PATCH') {
      updateBodies.push(request.postDataJSON() as Record<string, unknown>);
      await fulfillApi(route, { data: tournament });
      return;
    }

    await fulfillApi(route, { data: [] });
  });

  await page.goto(`/organizer/tournaments/${tournamentId}/manage`, { waitUntil: 'domcontentloaded' });
  const nameInput = page.getByTestId('manage-tournament-name-input');
  await expect(nameInput).toHaveValue('Original Tournament');
  await nameInput.fill('Edited Tournament');

  await expect.poll(() =>
    updateBodies.some((body) => body.name === 'Edited Tournament'),
  ).toBe(true);

  const updatedBody = updateBodies.find((body) => body.name === 'Edited Tournament');
  if (!updatedBody) throw new Error('Expected the edited tournament request body');
  expect(updatedBody).not.toHaveProperty('registrationMode');
  expect(updatedBody.tournamentConfig).toMatchObject({ registrationMode: 'APPROVAL' });
});

