import { expect, test, type Route } from '@playwright/test';

const tournamentId = 'synthetic-ops-tournament';
const divisionId = 'synthetic-ops-division';
const organizer = {
  id: 'synthetic-ops-organizer',
  email: 'organizer@example.test',
  fullName: 'Organizer Test',
  roles: ['ORGANIZER'],
  gender: 'MALE',
  isEmailVerified: true,
  profile: { fullName: 'Organizer Test' },
};
const tournament = {
  id: tournamentId,
  name: 'Synthetic Ops Tournament',
  status: 'PUBLISHED',
  matchType: 'SINGLES',
  genderRestriction: 'OPEN',
  entryFee: 0,
  maxParticipants: 16,
  isRegistrationLocked: false,
  category: { name: 'Tennis', slug: 'tennis' },
  tournamentConfig: {},
};
const division = {
  id: divisionId,
  name: 'Synthetic Ops Division',
  matchType: 'SINGLES',
  genderRestriction: 'OPEN',
  entryFee: 0,
  maxParticipants: 16,
  bracketType: 'ROUND_ROBIN',
  _count: { participants: 0 },
};

const nextTournamentId = 'synthetic-divisionless-tournament';
const nextTournament = { ...tournament, id: nextTournamentId, name: 'Divisionless Tournament' };

async function fulfillApi(route: Route, payload: unknown, status = 200) {
  const request = route.request();
  const requestHeaders = request.headers();
  const headers = {
    'access-control-allow-origin': requestHeaders.origin ?? 'http://localhost:3001',
    'access-control-allow-credentials': 'true',
    'access-control-allow-methods': 'GET, POST, OPTIONS',
    'access-control-allow-headers': requestHeaders['access-control-request-headers'] ?? 'authorization,content-type',
  };

  if (request.method() === 'OPTIONS') {
    await route.fulfill({ status: 204, headers });
    return;
  }

  await route.fulfill({ status, headers, json: payload });
}

test('Ops waits for metadata and suppresses stale scope on tournament route reuse', async ({ page }, testInfo) => {
  await page.addInitScript((user) => {
    localStorage.setItem('auth-storage', JSON.stringify({
      state: { user, isAuthenticated: true },
      version: 0,
    }));
  }, organizer);

  let releaseDivisions!: () => void;
  let signalDivisionRequest!: () => void;
  const divisionResponseGate = new Promise<void>((resolve) => {
    releaseDivisions = resolve;
  });
  const divisionRequestSeen = new Promise<void>((resolve) => {
    signalDivisionRequest = resolve;
  });
  let releaseNextDivisions!: () => void;
  let signalNextDivisionRequest!: () => void;
  const nextDivisionResponseGate = new Promise<void>((resolve) => {
    releaseNextDivisions = resolve;
  });
  const nextDivisionRequestSeen = new Promise<void>((resolve) => {
