import { expect, test, type Page, type Route } from '@playwright/test';

const tournamentId = 'synthetic-organizer-tournament';
const organizer = {
  id: 'synthetic-organizer',
  email: 'organizer@example.test',
  fullName: 'Organizer Test',
  phoneNumber: '0900000000',
  roles: ['ORGANIZER'],
  gender: 'MALE',
  isEmailVerified: true,
  profile: { fullName: 'Organizer Test', phoneNumber: '0900000000' },
};
const tournament = {
  id: tournamentId,
  name: 'Synthetic organizer tournament',
  status: 'PUBLISHED',
  matchType: 'DOUBLES',
  genderRestriction: 'MIXED',
  entryFee: 0,
  maxParticipants: 16,
  isRegistrationLocked: false,
  category: { name: 'Badminton', slug: 'badminton' },
  tournamentConfig: { registrationMode: 'APPROVAL', doublesPairingMode: 'ORGANIZER' },
};
const division = {
  id: 'synthetic-organizer-division',
  name: 'Synthetic organizer division',
  matchType: 'DOUBLES',
  genderRestriction: 'MIXED',
  entryFee: 0,
  maxParticipants: 16,
  bracketType: 'ROUND_ROBIN',
  _count: { participants: 0 },
};
const pendingParticipant = {
  id: 'synthetic-pending-participant',
  tournamentId,
  tournamentDivisionId: division.id,
  teamName: 'Pending doubles pair',
  teamStatus: 'PENDING_APPROVAL',
  isPaid: false,
  registeredAt: '2026-09-26T10:00:00.000Z',
  members: [{ userId: 'synthetic-player', fullName: 'Pending player', role: 'PLAYER' }],
};

async function fulfillApi(route: Route, payload: unknown, status = 200) {
  const request = route.request();
  const requestHeaders = request.headers();
  const headers = {
    'access-control-allow-origin': requestHeaders.origin ?? 'http://127.0.0.1:3001',
    'access-control-allow-credentials': 'true',
    'access-control-allow-methods': 'GET, POST, OPTIONS',
    'access-control-allow-headers': requestHeaders['access-control-request-headers'] ?? 'authorization,content-type',
  };

  if (request.method() === 'OPTIONS') {
    await route.fulfill({ status: 204, headers });
    return;
  }

  await route.fulfill({ status, headers, json: payload });
}

async function openOrganizerRegistration(
  page: Page,
  participantResponse: (route: Route) => Promise<void>,
  options: {
    divisions?: Array<typeof division>;
    autoSelectedDivisionId?: string;
    queryDivisionId?: string;
  } = {},
) {
  await page.addInitScript((user) => {
    localStorage.setItem('auth-storage', JSON.stringify({
      state: { user, isAuthenticated: true },
      version: 0,
    }));
  }, organizer);

  await page.route('**/api/v1/**', async (route) => {
    const request = route.request();
    const pathname = new URL(request.url()).pathname;

    if (pathname.endsWith('/users/profile')) {
      await fulfillApi(route, organizer);
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}/manage/participants`) {
      await participantResponse(route);
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}/divisions`) {
      await fulfillApi(route, { data: options.divisions ?? [division] });
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}`) {
      await fulfillApi(route, { data: tournament });
      return;
    }

    await fulfillApi(route, { data: [] });
  });

  const query = options.queryDivisionId ? `&divisionId=${encodeURIComponent(options.queryDivisionId)}` : '';
  await page.goto(`/organizer/tournaments/${tournamentId}/manage?tab=registration${query}`, { waitUntil: 'domcontentloaded' });
  const availableDivisions = options.divisions ?? [division];
  const selectedDivision = availableDivisions.find((item) => item.id === options.autoSelectedDivisionId) ?? division;
  const divisionButton = page.getByTestId(`manage-wide-division-${selectedDivision.id}`);
  await expect(divisionButton).toBeVisible();
  // The overlay keeps exactly one division selected, so selection is `aria-current`.
  if (options.autoSelectedDivisionId) {
    await expect(divisionButton).toHaveAttribute('aria-current', 'page');
  } else if (await divisionButton.getAttribute('aria-current') !== 'page') {
    await divisionButton.click();
  }
  await expect(page.getByRole('table')).toBeVisible();
}

test('organizer sees forbidden participant-list failures and can retry to pending rows', async ({ page }) => {
  let allowSuccessfulRead = false;
  const participantMethods: string[] = [];

  await openOrganizerRegistration(page, async (route) => {
    participantMethods.push(route.request().method());
    if (!allowSuccessfulRead) {
      await fulfillApi(route, { message: 'SENTINEL_FORBIDDEN_RESPONSE_BODY' }, 403);
      return;
    }
    await fulfillApi(route, { data: [pendingParticipant] });
  });

  const errorMessage = 'Không tải được hồ sơ đăng ký. Chưa thể xác nhận danh sách trống.';
  await expect(page.getByRole('alert').filter({ hasText: errorMessage })).toBeVisible();
  await expect(page.getByText('Không có hồ sơ phù hợp')).toHaveCount(0);
  await expect(page.getByText('SENTINEL_FORBIDDEN_RESPONSE_BODY')).toHaveCount(0);

  allowSuccessfulRead = true;
  await page.getByRole('button', { name: 'Thử lại' }).click();

  const pendingRow = page.getByRole('row').filter({ hasText: 'Pending doubles pair' });
  await expect(pendingRow).toBeVisible();
  await expect(pendingRow.getByTitle(/chờ.*duyệt/i)).toBeVisible();
  expect(participantMethods.length).toBeGreaterThanOrEqual(2);
  expect(participantMethods.every((method) => method === 'GET')).toBe(true);
});

test('organizer sees an empty state only after a successful participant-list response', async ({ page }) => {
  let participantReads = 0;

  await openOrganizerRegistration(page, async (route) => {
    participantReads += 1;
    await fulfillApi(route, { data: [] });
  });

  await expect(page.getByText('Không có hồ sơ phù hợp')).toBeVisible();
  await expect(page.getByRole('alert').filter({ hasText: 'Không tải được hồ sơ đăng ký. Chưa thể xác nhận danh sách trống.' })).toHaveCount(0);
  expect(participantReads).toBeGreaterThan(0);
});

test('organizer opens the division containing pending applications by default', async ({ page }) => {
  const pendingDivision = {
    ...division,
    id: 'synthetic-pending-division',
    name: 'Division with pending application',
  };
  const pendingInDivision = {
    ...pendingParticipant,
    tournamentDivisionId: pendingDivision.id,
  };

  await openOrganizerRegistration(
    page,
    async (route) => {
      await fulfillApi(route, { data: [pendingInDivision] });
    },
    {
      divisions: [division, pendingDivision],
      autoSelectedDivisionId: pendingDivision.id,
    },
  );

  await expect(page.getByRole('row').filter({ hasText: 'Pending doubles pair' })).toBeVisible();
});

test('organizer URL division selection takes priority over pending auto-focus', async ({ page }) => {
  const pendingDivision = {
    ...division,
    id: 'synthetic-pending-division',
    name: 'Division with pending application',
  };
  const pendingInDivision = {
    ...pendingParticipant,
    tournamentDivisionId: pendingDivision.id,
  };

  await openOrganizerRegistration(
    page,
    async (route) => {
      await fulfillApi(route, { data: [pendingInDivision] });
    },
    {
      divisions: [division, pendingDivision],
      autoSelectedDivisionId: division.id,
      queryDivisionId: division.id,
    },
  );
});

test('organizer keeps the first division when no pending applications exist', async ({ page }) => {
  await openOrganizerRegistration(
    page,
    async (route) => {
      await fulfillApi(route, { data: [] });
    },
    {
      divisions: [division, { ...division, id: 'synthetic-second-division', name: 'Second division' }],
      autoSelectedDivisionId: division.id,
    },
  );

  await expect(page.getByRole('row').filter({ hasText: 'Pending doubles pair' })).toHaveCount(0);
});

