      autoSelectedDivisionId: pendingDivision.id,
    },
  );

  await expect(page.getByRole('row').filter({ hasText: 'Pending doubles pair' })).toBeVisible();
});

test('organizer URL division selection takes priority over pending auto-focus', async ({ page }) => {
  const pendingDivision = {
    ...division,
    id: 'synthetic-pending-division',
    name: 'Division with pending application',
  };
  const pendingInDivision = {
    ...pendingParticipant,
