test('organizer keeps the first division when no pending applications exist', async ({ page }) => {
  await openOrganizerRegistration(
    page,
    async (route) => {
      await fulfillApi(route, { data: [] });
    },
    {
      divisions: [division, { ...division, id: 'synthetic-second-division', name: 'Second division' }],
      autoSelectedDivisionId: division.id,
    },
