import { expect, test, type Page, type Route } from '@playwright/test';

const tournamentId = 'synthetic-venue-registration-tournament';
const dayMs = 24 * 60 * 60 * 1000;
const organizer = {
  id: 'synthetic-organizer',
  email: 'organizer@example.test',
  fullName: 'Organizer Test',
  phoneNumber: '0900000000',
  roles: ['ORGANIZER'],
  gender: 'MALE',
  isEmailVerified: true,
  profile: { fullName: 'Organizer Test', phoneNumber: '0900000000' },
};

type MockVenue = {
  id: string;
  name: string;
  locationAddress: string;
  isDefault?: boolean;
  courts: Array<{ id: string; name: string }>;
};

type MockTournament = {
  id: string;
  name: string;
  status: string;
  matchType: string;
  genderRestriction: string;
  entryFee: number;
  maxParticipants: number;
  isRegistrationLocked: boolean;
  registrationStartDate: string;
  registrationEndDate: string;
  startDate: string;
  endDate: string;
  category: { name: string; slug: string };
  tournamentConfig: Record<string, unknown>;
};

type MockContext = {
  tournament: MockTournament;
  savedVenues: MockVenue[];
  attachedVenues: MockVenue[];
  venueAttachments: Array<Record<string, unknown>>;
  registrationUpdates: Array<Record<string, unknown>>;
};

function makeTournament(overrides: Partial<MockTournament> = {}): MockTournament {
  const now = Date.now();
  return {
    id: tournamentId,
    name: 'Synthetic organizer tournament',
    status: 'PUBLISHED',
    matchType: 'DOUBLES',
    genderRestriction: 'MIXED',
    entryFee: 0,
    maxParticipants: 16,
    isRegistrationLocked: false,
    registrationStartDate: new Date(now - dayMs).toISOString(),
    registrationEndDate: new Date(now + dayMs).toISOString(),
    startDate: new Date(now + 10 * dayMs).toISOString(),
    endDate: new Date(now + 12 * dayMs).toISOString(),
    category: { name: 'Badminton', slug: 'badminton' },
    tournamentConfig: { registrationMode: 'OPEN', doublesPairingMode: 'ORGANIZER' },
    ...overrides,
  };
}

async function fulfillApi(route: Route, payload: unknown, status = 200) {
  const request = route.request();
  const requestHeaders = request.headers();
  const headers = {
    'access-control-allow-origin': requestHeaders.origin ?? 'http://127.0.0.1:3101',
    'access-control-allow-credentials': 'true',
    'access-control-allow-methods': 'GET, POST, PATCH, OPTIONS',
    'access-control-allow-headers': requestHeaders['access-control-request-headers'] ?? 'authorization,content-type',
  };

  if (request.method() === 'OPTIONS') {
    await route.fulfill({ status: 204, headers });
    return;
  }
  await route.fulfill({ status, headers, json: payload });
}

async function fulfillManageRequest(route: Route, context: MockContext) {
  const request = route.request();
  const pathname = new URL(request.url()).pathname;

  if (pathname.endsWith('/users/profile')) {
    await fulfillApi(route, organizer);
    return;
  }
  if (pathname === `/api/v1/tournaments/${tournamentId}` && request.method() === 'PATCH') {
    const update = request.postDataJSON() as Record<string, unknown>;
    context.registrationUpdates.push(update);
    context.tournament = {
      ...context.tournament,
      ...update,
      tournamentConfig: {
        ...context.tournament.tournamentConfig,
        ...(update.tournamentConfig as Record<string, unknown> | undefined),
      },
    };
    await fulfillApi(route, { data: context.tournament });
    return;
  }
  if (pathname === `/api/v1/tournaments/${tournamentId}`) {
    await fulfillApi(route, { data: context.tournament });
    return;
  }
  if (pathname === `/api/v1/tournaments/${tournamentId}/venues` && request.method() === 'POST') {
    const attachment = request.postDataJSON() as Record<string, unknown>;
    context.venueAttachments.push(attachment);
    const savedVenue = context.savedVenues.find((venue) => venue.id === attachment.venueId);
    if (savedVenue) context.attachedVenues.push({ ...savedVenue, isDefault: false });
    await fulfillApi(route, { data: savedVenue ?? attachment });
    return;
  }
  if (pathname === `/api/v1/tournaments/${tournamentId}/venues`) {
    await fulfillApi(route, { data: context.attachedVenues });
    return;
  }
  if (pathname === '/api/v1/venues') {
    await fulfillApi(route, { data: context.savedVenues });
    return;
  }
  if (pathname === `/api/v1/tournaments/${tournamentId}/divisions`) {
    await fulfillApi(route, { data: [] });
    return;
  }
  await fulfillApi(route, { data: [] });
}

async function openOrganizerManage(
  page: Page,
  tab: 'schedule' | 'settings',
  options: { savedVenues?: MockVenue[]; attachedVenues?: MockVenue[]; tournament?: MockTournament } = {},
) {
  const context: MockContext = {
    tournament: options.tournament ?? makeTournament(),
    savedVenues: options.savedVenues ?? [],
    attachedVenues: [...(options.attachedVenues ?? [])],
    venueAttachments: [],
    registrationUpdates: [],
  };

  await page.addInitScript((user) => {
    localStorage.setItem('auth-storage', JSON.stringify({
      state: { user, isAuthenticated: true },
      version: 0,
    }));
  }, organizer);
  await page.route('**/api/v1/**', (route) => fulfillManageRequest(route, context));
  await page.goto(`/organizer/tournaments/${tournamentId}/manage?tab=${tab}`, { waitUntil: 'domcontentloaded' });
  return context;
}

test.use({ timezoneId: 'UTC' });

test('organizer can attach an unattached saved venue and it leaves the picker afterward', async ({ page }) => {
  const savedVenue: MockVenue = {
    id: 'saved-moc-venue',
    name: 'Mộc',
    locationAddress: '12 Đường Sân Cầu',
    courts: [],
  };
  const context = await openOrganizerManage(page, 'schedule', { savedVenues: [savedVenue] });

  await page.getByRole('button', { name: 'Thêm địa điểm mới', exact: true }).click();
  const savedVenueOption = page.locator('select option[value="saved-moc-venue"]');
  await expect(savedVenueOption).toHaveText(/Mộc/);
  await page.locator('select:has(option[value="saved-moc-venue"])').selectOption(savedVenue.id);
  await page.getByRole('button', { name: /Dùng địa điểm này|Use this venue/i }).click();

  await expect.poll(() => context.venueAttachments.length).toBe(1);
  expect(context.venueAttachments[0]).toMatchObject({ venueId: savedVenue.id });
  await page.getByRole('button', { name: 'Thêm địa điểm mới', exact: true }).click();
  await expect(page.locator('select option[value="saved-moc-venue"]')).toHaveCount(0);
});

test('court counts are bold on the schedule and venue selector', async ({ page }) => {
  const attachedVenue: MockVenue = {
    id: 'attached-court-venue',
    name: 'Sân Mộc',
    locationAddress: '12 Đường Sân Cầu',
    isDefault: true,
    courts: [
      { id: 'court-1', name: 'Sân 1' },
      { id: 'court-2', name: 'Sân 2' },
    ],
  };
  await openOrganizerManage(page, 'schedule', { attachedVenues: [attachedVenue] });

  const courtSettingsButton = page.getByRole('button').filter({ hasText: 'Cài đặt sân' });
  await expect(courtSettingsButton).toBeVisible();
  const courtCountBadge = page.getByText('2 sân thi đấu', { exact: true });
  await expect(courtCountBadge.locator('span').first()).toHaveCSS('font-weight', '800');
  await expect(courtSettingsButton.locator('span').filter({ hasText: '(2)' })).toHaveCSS('font-weight', '800');

  await courtSettingsButton.click();
  const venueTab = page.getByRole('button', { name: /Sân Mộc/ });
  await expect(venueTab).toBeVisible();
  await expect(venueTab.locator('span').last()).toHaveCSS('font-weight', '800');
});

test('organizer can extend the deadline during an open, unlocked registration window', async ({ page }) => {
  const tournament = makeTournament();
  const oldDeadline = Date.parse(tournament.registrationEndDate);
  const context = await openOrganizerManage(page, 'settings', { tournament });
  const endDateInput = page.locator('input[placeholder*="/"]').nth(1);
  await expect(endDateInput).toBeEnabled();

  const extendedDeadline = new Date(Date.now() + 4 * dayMs);
  const dateText = `${String(extendedDeadline.getUTCDate()).padStart(2, '0')}/${String(extendedDeadline.getUTCMonth() + 1).padStart(2, '0')}/${extendedDeadline.getUTCFullYear()} ${String(extendedDeadline.getUTCHours()).padStart(2, '0')}:${String(extendedDeadline.getUTCMinutes()).padStart(2, '0')}`;
  await endDateInput.fill(dateText);
  await page.getByRole('button', { name: /Lưu cài đặt|Save settings/i }).click();

  await expect.poll(() => context.registrationUpdates.length).toBe(1);
  expect(Date.parse(String(context.registrationUpdates[0].registrationEndDate))).toBeGreaterThan(oldDeadline);
});

test('organizer can extend a closed registration deadline without reopening registration', async ({ page }) => {
  const tournament = makeTournament({
    status: 'REGISTRATION_CLOSED',
    isRegistrationLocked: false,
    registrationEndDate: new Date(Date.now() - dayMs).toISOString(),
  });
  const context = await openOrganizerManage(page, 'settings', { tournament });
  const registrationInputs = page.locator('input[placeholder*="/"]');
  const startDateInput = registrationInputs.nth(0);
  const endDateInput = registrationInputs.nth(1);
  await expect(startDateInput).toBeDisabled();
  await expect(endDateInput).toBeEnabled();

  const extendedDeadline = new Date(Date.now() + 6 * dayMs);
  const dateText = `${String(extendedDeadline.getUTCDate()).padStart(2, '0')}/${String(extendedDeadline.getUTCMonth() + 1).padStart(2, '0')}/${extendedDeadline.getUTCFullYear()} ${String(extendedDeadline.getUTCHours()).padStart(2, '0')}:${String(extendedDeadline.getUTCMinutes()).padStart(2, '0')}`;
  await endDateInput.fill(dateText);
  await page.getByRole('button', { name: /Lưu cài đặt|Save settings/i }).click();

  await expect.poll(() => context.registrationUpdates.length).toBe(1);
  expect(context.registrationUpdates[0]).toEqual({
    registrationEndDate: expect.any(String),
  });
  expect(context.tournament).toMatchObject({
    status: 'REGISTRATION_CLOSED',
    isRegistrationLocked: false,
  });
});


test('registration-specific lock keeps deadline editing disabled', async ({ page }) => {
  await openOrganizerManage(page, 'settings', {
    tournament: makeTournament({ isRegistrationLocked: true }),
  });
  await expect(page.locator('input[placeholder*="/"]').nth(1)).toBeDisabled();
});

