test('requires a sufficient preview before sequentially committing a workbook larger than one API batch', async ({ page }) => {
  await page.setViewportSize({ width: 1600, height: 900 });
  await openManage(page);

  await page.getByTestId('manage-tab-registration').click();
  const divisionButton = page.getByRole('button', { name: new RegExp(division.name, 'i') });
  if (await divisionButton.getAttribute('aria-expanded') !== 'true') {
    await divisionButton.click();
  }

  const previewBatchSizes: number[] = [];
  const commitBatchSizes: number[] = [];
  let capacityRemaining = 200;
  await page.route(`**/api/v1/tournaments/${tournamentId}/import-participants/preview`, async (route) => {
    if (route.request().method() === 'OPTIONS') {
      await fulfillApi(route, {});
      return;
    }
    const { participants } = route.request().postDataJSON() as {
      participants: Array<Record<string, unknown>>;
    };
    previewBatchSizes.push(participants.length);
    if (participants.length > 200) {
      await fulfillApi(route, { message: 'Batch exceeds 200 rows' }, 400);
      return;
    }
    await fulfillApi(route, {
      data: {
        divisionMatched: true,
        requestedTeamSlots: participants.length,
        capacityRemaining,
        rows: participants.map((participant, rowIndex) => ({
          ...participant,
          rowIndex,
          status: ['NOT_FOUND'],
          isEligible: true,
          capacityDelta: 1,
        })),
      },
    });
  });
  await page.route(`**/api/v1/tournaments/${tournamentId}/roster-import`, async (route) => {
    if (route.request().method() === 'OPTIONS') {
      await fulfillApi(route, {});
      return;
    }
    const { participants } = route.request().postDataJSON() as {
      participants: Array<Record<string, unknown>>;
    };
    commitBatchSizes.push(participants.length);
    if (participants.length > 200) {
      await fulfillApi(route, { message: 'Batch exceeds 200 rows' }, 400);
      return;
    }
    await fulfillApi(route, {
      data: { message: 'Imported', importedCount: participants.length },
    });
  });

  await page.getByRole('button', { name: 'Nhập Excel' }).click();

  const rows = Array.from({ length: 201 }, (_, index) => [
    `Player ${index + 1}`,
    `player-${index + 1}@example.test`,
  ]);
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(
    workbook,
    XLSX.utils.aoa_to_sheet([
      ['Player 1 name', 'Player 1 email (required)'],
      ...rows,
    ]),
    'Roster',
  );
  const buffer = XLSX.write(workbook, { bookType: 'xlsx', type: 'buffer' }) as Buffer;
  await page.locator('input[type="file"][accept*=".xlsx"]').setInputFiles({
    name: 'roster.xlsx',
    mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    buffer,
  });

  await page.getByRole('button', { name: 'Xem danh sách VĐV' }).click();
  const confirmButton = page.getByRole('button', { name: 'Xác nhận thêm 201 VĐV' });
  await expect(confirmButton).toBeDisabled();
  await page.getByRole('button', { name: 'Kiểm tra danh sách' }).click();
  await expect.poll(() => previewBatchSizes).toEqual([200, 1]);
  await expect(confirmButton).toBeDisabled();

  capacityRemaining = 500;
  await page.getByRole('dialog').locator('table input').first().fill('Updated team name');
  await page.getByRole('button', { name: 'Kiểm tra danh sách' }).click();
  await expect.poll(() => previewBatchSizes).toEqual([200, 1, 200, 1]);
  await expect(confirmButton).toBeEnabled();

  await confirmButton.click();
  await expect.poll(() => commitBatchSizes).toEqual([200, 1]);
  // The roster dialog closes; the manage overlay it was opened from stays.
  await expect(page.getByTestId('roster-import-modal')).toHaveCount(0);
  await expect(page.getByTestId('manage-wide-overlay')).toBeVisible();
});
