/**
 * Minimal stand-in for the tournament API, used only by
 * `tournament-participants-profile-navigation.spec.ts`.
 *
 * The public tournament detail route is a server component: `page.tsx` calls
 * `getTournament()` during SSR and renders `notFound()` when that read fails.
 * Playwright's `page.route` only intercepts browser traffic, so a fully
 * synthetic tournament cannot be rendered without a real backend behind
 * `NEXT_API_URL`.
 *
 * Start it with:
 *   node test/e2e/fixtures/tournament-mock-api.mjs        # listens on :8799
 * and run the dev server with:
 *   NEXT_API_URL=http://127.0.0.1:8799/api/v1 npm run dev
 *
 * The browser-side calls are still stubbed by the spec itself; this process
 * only has to satisfy the server render.
 */
import { createServer } from 'node:http';

export const TOURNAMENT_ID = 'synthetic-participants-tournament';

const SINGLES_TOURNAMENT = {
  id: TOURNAMENT_ID,
  name: 'Synthetic participants tournament',
  status: 'PUBLISHED',
  matchType: 'SINGLES',
  genderRestriction: 'MALE',
  entryFee: 0,
  maxParticipants: 32,
  isRegistrationLocked: false,
  startDate: '2026-09-01T00:00:00.000Z',
  endDate: '2026-09-30T00:00:00.000Z',
  category: { name: 'Badminton', slug: 'badminton' },
  tournamentConfig: { registrationMode: 'APPROVAL' },
  _count: { participants: 2, matches: 0 },
};

const SINGLES_PARTICIPANTS = [
  {
    id: 'synthetic-participant-singles',
    teamName: 'Vận động viên Alpha',
    teamStatus: 'COMPLETE',
    isPaid: true,
    seed: 1,
    registeredAt: '2026-09-02T00:00:00.000Z',
    registeredBy: { id: 'synthetic-athlete-alpha', fullName: 'Vận động viên Alpha', avatarUrl: null },
    members: [
      {
        userId: 'synthetic-athlete-alpha',
        fullName: 'Vận động viên Alpha',
        avatarUrl: null,
        role: 'MAIN',
        elo: { eloPoints: 1520, tierName: 'Gold' },
      },
    ],
  },
  {
    id: 'synthetic-participant-singles-2',
    teamName: 'Vận động viên Beta',
    teamStatus: 'COMPLETE',
    isPaid: true,
    seed: 2,
    registeredAt: '2026-09-03T00:00:00.000Z',
    registeredBy: { id: 'synthetic-athlete-beta', fullName: 'Vận động viên Beta', avatarUrl: null },
    members: [
      {
        userId: 'synthetic-athlete-beta',
        fullName: 'Vận động viên Beta',
        avatarUrl: null,
        role: 'MAIN',
        elo: { eloPoints: 1410, tierName: 'Silver' },
      },
    ],
  },
];

const DOUBLES_TOURNAMENT = {
  ...SINGLES_TOURNAMENT,
  id: `${TOURNAMENT_ID}-doubles`,
  name: 'Synthetic doubles tournament',
  matchType: 'DOUBLES',
  genderRestriction: 'MIXED',
  tournamentConfig: { registrationMode: 'APPROVAL', doublesPairingMode: 'ORGANIZER' },
};

const DOUBLES_PARTICIPANTS = [
  {
    id: 'synthetic-participant-doubles',
    teamName: 'Đôi Kim Cương',
    teamStatus: 'COMPLETE',
    isPaid: true,
    seed: 1,
    registeredAt: '2026-09-02T00:00:00.000Z',
    registeredBy: { id: 'synthetic-athlete-diamond', fullName: 'Vận động viên Kim', avatarUrl: null },
    members: [
      {
        userId: 'synthetic-athlete-diamond',
        fullName: 'Vận động viên Kim',
        avatarUrl: null,
        role: 'MAIN',
        elo: { eloPoints: 1600, tierName: 'Diamond' },
      },
      {
        userId: 'synthetic-athlete-ruby',
        fullName: 'Vận động viên Ngọc',
        avatarUrl: null,
        role: 'MAIN',
        elo: { eloPoints: 1580, tierName: 'Diamond' },
      },
    ],
  },
];

const RESULTS = {
  tournamentId: TOURNAMENT_ID,
  status: 'COMPLETED',
  finalized: true,
  standings: [],
  matches: [],
  awards: [
    {
      rank: 1,
      shared: false,
      participant: {
        participantId: 'synthetic-participant-podium-1',
        teamName: 'Đôi Kim Cương',
        members: [{ userId: 'synthetic-athlete-champion', fullName: 'Vận động viên Vô địch', avatarUrl: null }],
      },
    },
    {
      rank: 2,
      shared: false,
      participant: {
        participantId: 'synthetic-participant-podium-2',
        teamName: 'Đôi Bạc',
        members: [{ userId: 'synthetic-athlete-runner-up', fullName: 'Vận động viên Á quân', avatarUrl: null }],
      },
    },
  ],
};

const TOURNAMENTS = {
  [TOURNAMENT_ID]: SINGLES_TOURNAMENT,
  [DOUBLES_TOURNAMENT.id]: DOUBLES_TOURNAMENT,
};

const PARTICIPANTS = {
  [TOURNAMENT_ID]: SINGLES_PARTICIPANTS,
  [DOUBLES_TOURNAMENT.id]: DOUBLES_PARTICIPANTS,
};

const CORS = {
  'access-control-allow-origin': '*',
  'access-control-allow-credentials': 'true',
  'access-control-allow-methods': 'GET, POST, PATCH, DELETE, OPTIONS',
  'access-control-allow-headers': '*',
};

function send(response, status, body) {
  response.writeHead(status, { ...CORS, 'content-type': 'application/json' });
  response.end(JSON.stringify(body));
}

function resolve({ pathname }) {
  const match = pathname.match(/^\/api\/v1\/tournaments\/([^/]+)(\/(.*))?$/);
  if (!match) return null;
  const [, id, , rest = ''] = match;
  if (!(id in TOURNAMENTS)) return null;

  if (rest === 'divisions') return { data: [] };
  if (rest === 'results') return { data: id === TOURNAMENT_ID ? RESULTS : { ...RESULTS, tournamentId: id, awards: [] } };
  if (rest === 'participants') return { data: PARTICIPANTS[id] ?? [] };
  if (rest === '') return { data: TOURNAMENTS[id] };
  return null;
}

const port = Number(process.env.MOCK_API_PORT ?? 8799);
const server = createServer((request, response) => {
  const { pathname } = new URL(request.url ?? '/', `http://127.0.0.1:${port}`);
  if (request.method === 'OPTIONS') {
    response.writeHead(204, CORS);
    response.end();
    return;
  }

  const payload = resolve({ pathname });
  if (payload) {
    send(response, 200, payload);
    return;
  }

  send(response, 200, { data: [] });
});

server.listen(port, '127.0.0.1', () => {
  console.log(`[tournament-mock-api] listening on http://127.0.0.1:${port}/api/v1`);
});

