/**
 * The schedule card's live/selected contract.
 *
 * The bug this guards: `buildScheduleCardRows` resolved `selected` before
 * `isActiveMatch`, so a live match inside the organizer selection range painted
 * amber and the rose live treatment was unreachable. The fix is composite —
 * `live` owns the palette and the selection is layered on top — so both signals
 * have to survive every combination, not just the one that was reported.
 *
 * Server-free assertions over the two pure modules and the class contract the
 * card renders from. This is not a running-app check: no page is loaded, so it
 * cannot catch a Tailwind purge or a stylesheet regression. It does catch the
 * variant ordering and the selection/live palette split, which is what broke.
 */

import { expect, test } from '@playwright/test';
import {
  LIVE_PILL,
  SCHEDULE_CARD_SELECTION,
  getScheduleCardChrome,
} from '@/components/tournaments/schedule/ScheduleMatchCard';
import { buildScheduleCardRows } from '@/components/tournaments/schedule/schedule-card-rows';

type Transient = { selected: boolean; draft: boolean; preview: boolean };

/** Every organizer transient combination the court schedule can hand the card. */
const COMBINATIONS: Transient[] = (
  [
    [false, false, false],
    [true, false, false],
    [false, true, false],
    [false, false, true],
    [true, true, false],
    [true, false, true],
    [false, true, true],
    [true, true, true],
  ] as const
).map(([selected, draft, preview]) => ({ selected, draft, preview }));

function matchWithStatus(status: string) {
  return {
    id: 'card-contract-match',
    status,
    participant1: { id: 'p1', fullName: 'Alpha' },
    participant2: { id: 'p2', fullName: 'Beta' },
  } as unknown as Parameters<typeof buildScheduleCardRows>[0]['match'];
}

function competitors() {
  return {
    competitor1: { avatars: [{ initial: 'A' }], displayLabel: 'Alpha', fullName: 'Alpha' },
    competitor2: { avatars: [{ initial: 'B' }], displayLabel: 'Beta', fullName: 'Beta' },
  };
}

function rows(status: string, transient: Transient, setList: Array<{ s1: number; s2: number }> = []) {
  return buildScheduleCardRows({
    match: matchWithStatus(status),
    ...competitors(),
    setList,
    isFootball: false,
    ...transient,
  });
}

test('a live match keeps the live palette through every organizer transient', () => {
  for (const transient of COMBINATIONS) {
    const { variant, selected } = rows('IN_PROGRESS', transient);

    expect(variant, `live + ${JSON.stringify(transient)}`).toBe('live');
    // The selection rides alongside the variant instead of being consumed by it,
    // so the caller can still paint the ring and the "Đang chọn" badge.
    expect(selected, `live + ${JSON.stringify(transient)} reports the selection`).toBe(
      transient.selected,
    );
  }
});

test('a live match that already has a recorded set still paints as live', () => {
  const recorded = [{ s1: 21, s2: 14 }];

  // Without the live check the recorded set alone would close the card out.
  expect(rows('SCHEDULED', COMBINATIONS[0], recorded).variant).toBe('done');
  expect(rows('ONGOING', COMBINATIONS[1], recorded).variant).toBe('live');
  expect(rows('LIVE', COMBINATIONS[0], recorded).variant).toBe('live');
});

test('a match that is not live still resolves the transients it always did', () => {
  expect(rows('SCHEDULED', COMBINATIONS[0]).variant).toBe('scheduled');
  expect(rows('SCHEDULED', COMBINATIONS[1]).variant).toBe('selected');
  expect(rows('SCHEDULED', COMBINATIONS[2]).variant).toBe('draft');
  expect(rows('SCHEDULED', COMBINATIONS[3]).variant).toBe('preview');
  expect(rows('COMPLETED', COMBINATIONS[0]).variant).toBe('done');
  expect(rows('FINISHED', COMBINATIONS[0]).variant).toBe('done');
  // Selection outranks the unsaved/preview transients, as it did before.
  expect(rows('SCHEDULED', COMBINATIONS[4]).variant).toBe('selected');
  expect(rows('SCHEDULED', COMBINATIONS[5]).variant).toBe('selected');
  expect(rows('SCHEDULED', COMBINATIONS[6]).variant).toBe('draft');
  expect(rows('SCHEDULED', COMBINATIONS[7]).variant).toBe('selected');
});

test('a live+selected card renders rose chrome, not the amber selection palette', () => {
  const { variant } = rows('IN_PROGRESS', COMBINATIONS[1]);
  const chrome = getScheduleCardChrome(variant);

  expect(variant).toBe('live');
  expect(chrome.surface).toContain('border-rose-500');
  expect(chrome.header).toContain('rose');
  expect(chrome.row).toContain('rose');
  expect(chrome.statusText).toContain('rose');
  expect(chrome.accent).toContain('rose');

  // The amber palette is nowhere on a live card...
  const amberChrome = getScheduleCardChrome('selected');
  expect(amberChrome.surface).toContain('border-amber-500');
  expect(chrome.surface).not.toBe(amberChrome.surface);
  expect(chrome.header).not.toBe(amberChrome.header);
  expect(chrome.row).not.toBe(amberChrome.row);

  // ...but the selection still reads, because the affordance is layered on top
  // of the palette rather than swapped for it. The cue is a thicker ring plus a
  // brand gradient that pops in once on selection and then keeps turning; the
  // name is kept for assistive tech only, so the card header stays free for
  // the court code and start time.
  expect(SCHEDULE_CARD_SELECTION.ring).toContain('ring-[3px]');
  expect(SCHEDULE_CARD_SELECTION.halo).toContain('-inset-[3px]');
  expect(SCHEDULE_CARD_SELECTION.halo).toContain('animate-[schedule-selection-pop');
  expect(SCHEDULE_CARD_SELECTION.haloGradient).toContain('conic-gradient');
  expect(SCHEDULE_CARD_SELECTION.haloGradient).toContain('var(--color-amber-500)');
  expect(SCHEDULE_CARD_SELECTION.haloGradient).toContain('animate-[spin');
  expect(SCHEDULE_CARD_SELECTION.haloGradient).toContain('motion-reduce:animate-none');
  expect(SCHEDULE_CARD_SELECTION.label).toBe('Đang chọn');
  expect(LIVE_PILL).toContain('rose');
});

test('winner shading follows the result, not the selection', () => {
  const finished = rows('COMPLETED', COMBINATIONS[1], [{ s1: 21, s2: 14 }]);

  expect(finished.variant).toBe('selected');
  expect(finished.competitors.map((row) => row.won)).toEqual([true, false]);

  // Same for a live card that already carries a set: the palette says live,
  // the winner shading still follows the recorded aggregate.
  const liveFinished = rows('IN_PROGRESS', COMBINATIONS[1], [{ s1: 14, s2: 21 }]);
  expect(liveFinished.variant).toBe('live');
  expect(liveFinished.competitors.map((row) => row.won)).toEqual([false, true]);
});

